event_logger0_seq: process (CLK100MHZ) is
begin
    if rising_edge(CLK100MHZ) then
        event_logger0_prev <= candado_core0_state_code;
        event_logger0_tstart <= '0';
        if bool(rst) then
            event_logger0_phase <= to_unsigned(0, 2);
            event_logger0_pending <= '0';
            event_logger0_idx <= to_unsigned(0, 4);
        else
            case event_logger0_phase is
                when "00" =>
                    if bool(event_logger0_pending) then
                        event_logger0_msg_state <= event_logger0_pend_state;
                        event_logger0_msg_fail <= candado_core0_fail;
                        event_logger0_idx <= to_unsigned(0, 4);
                        event_logger0_pending <= '0';
                        event_logger0_phase <= to_unsigned(1, 2);
                    end if;
                when "01" =>
                    if (not bool(event_logger0_tbusy)) then
                        event_logger0_tstart <= '1';
                        event_logger0_phase <= to_unsigned(2, 2);
                    end if;
                when "10" =>
                    event_logger0_phase <= to_unsigned(3, 2);
                when others =>
                    if (not bool(event_logger0_tbusy)) then
                        if (event_logger0_idx = 11) then
                            event_logger0_phase <= to_unsigned(0, 2);
                        else
                            event_logger0_idx <= (event_logger0_idx + 1);
                            event_logger0_phase <= to_unsigned(1, 2);
                        end if;
                    end if;
            end case;
            if ((candado_core0_state_code /= event_logger0_prev) and (candado_core0_state_code /= 2)) then
                event_logger0_pending <= '1';
                event_logger0_pend_state <= candado_core0_state_code;
            end if;
        end if;
    end if;
end process event_logger0_seq;

